import math

def control(obs):
    look_deg = -23.0
    speed_mps = -0.8
    hitch_deg = obs.get('hitch_deg', 0.0)
    views = obs.get('views', {})
    cam = views.get('camera')

    desired_hitch = 0.0
    left_dist = 999.0
    right_dist = 999.0

    if cam and 'walls' in cam and cam['walls']:
        trailer_hdg = obs.get('rig', {}).get('trailer_heading_deg', -hitch_deg)
        for b_deg, d in cam['walls']:
            rel_angle = (b_deg - (trailer_hdg + 180.0) + 180.0) % 360.0 - 180.0
            lat = d * math.sin(math.radians(rel_angle))
            long_dist = d * math.cos(math.radians(rel_angle))
            if long_dist > 0.2:
                if lat > 0 and lat < left_dist:
                    left_dist = lat
                elif lat < 0 and -lat < right_dist:
                    right_dist = -lat

        if left_dist < 900 and right_dist < 900:
            corridor_err = left_dist - right_dist
            desired_hitch = max(-18.0, min(18.0, corridor_err * 15.0))
        elif left_dist < 1.2:
            desired_hitch = -8.0
        elif right_dist < 1.2:
            desired_hitch = 8.0

    if cam and 'target_corners' in cam and cam['target_corners']:
        pts = cam['target_corners']
        trailer_hdg = obs.get('rig', {}).get('trailer_heading_deg', -hitch_deg)
        avg_rel = sum(((b - (trailer_hdg + 180.0) + 180.0) % 360.0 - 180.0) for b, d in pts) / len(pts)
        desired_hitch = max(-20.0, min(20.0, avg_rel * 0.8))
    elif obs.get('target', {}).get('in_sight') and 'bearing_deg' in obs['target']:
        rel_back = (obs['target']['bearing_deg'] - 180.0 + 180.0) % 360.0 - 180.0
        desired_hitch = max(-20.0, min(20.0, rel_back * 0.5))

    hitch_err = hitch_deg - desired_hitch
    steer_deg = hitch_err * 2.2
    steer_deg = max(-34.0, min(34.0, steer_deg))

    if abs(hitch_deg) > 30.0:
        speed_mps = 0.5
        steer_deg = -hitch_deg * 1.0

    return (steer_deg, speed_mps, look_deg)

