import math

phase = 'UNPIN_FORWARD'
fwd_dist = 0.0
prev_hitch = 11.0

def control(obs):
    global phase, fwd_dist, prev_hitch
    dt = obs.get('dt', 0.1)
    hold_s = obs.get('motion', {}).get('hold_s', 0.0)
    hitch_deg = obs.get('hitch_deg', 0.0)
    prog = obs.get('progress', {}).get('covered', 9.3)
    v_mps = obs.get('motion', {}).get('v_mps', 0.0)

    look_deg = 64.0
    if hold_s > 0.0:
        return {'steer_deg': 0.0, 'speed_mps': 0.0, 'look_deg': look_deg}

    # Pull forward ~3.2m with neutral/mild steer to clear tight corner
    if phase == 'UNPIN_FORWARD':
        if v_mps > 0.05:
            fwd_dist += v_mps * dt
        if fwd_dist < 3.2:
            return {'steer_deg': -2.0, 'speed_mps': 0.8, 'look_deg': 0.0}
        else:
            phase = 'REVERSE_CAREFUL'

    # Safe corridor tracking
    views = obs.get('views', {})
    left_clearance = 99.0
    right_clearance = 99.0

    for vname, vdata in views.items():
        orig = vdata.get('origin', [0, 0])
        for b_deg, d in vdata.get('walls', []):
            rad = math.radians(b_deg)
            px = orig[0] + d * math.cos(rad)
            py = orig[1] + d * math.sin(rad)
            if -7.0 <= px <= 2.5:
                if py > 0:
                    left_clearance = min(left_clearance, py)
                else:
                    right_clearance = min(right_clearance, abs(py))

    target_hitch = 0.0
    if prog > 8.0 and prog < 19.0:
        target_hitch = 12.0
    elif prog >= 19.0 and prog < 30.0:
        target_hitch = -12.0
    elif prog >= 30.0:
        target_hitch = 0.0

    if right_clearance < 1.7:
        target_hitch += (1.7 - right_clearance) * 15.0
    if left_clearance < 1.7:
        target_hitch -= (1.7 - left_clearance) * 15.0

    target_hitch = max(-20.0, min(20.0, target_hitch))

    dhitch = (hitch_deg - prev_hitch) / max(0.01, dt)
    prev_hitch = hitch_deg

    err = hitch_deg - target_hitch
    steer = 1.8 * err + 0.3 * dhitch
    steer = max(-30.0, min(30.0, steer))

    t_sim = obs.get('t', 0.0)
    look_deg = 64.0 if (int(t_sim / 2.0) % 2 == 0) else -64.0

    return {'steer_deg': steer, 'speed_mps': -0.5, 'look_deg': look_deg}

