import math

# 6 rail touches out of 8 max! We must NOT touch rails again.
# Every touch was trailer rear-right corner touching at progress ~8.3m to 9.9m.
# Right rail sweeps inwards to the left. The trailer MUST swing left (positive hitch angle ~ +12 to +15 deg) before entering.

state = 'PULL_FWD'
unpin_fwd = 0.0
prev_hitch = 1.4

def control(obs):
    global state, unpin_fwd, prev_hitch
    dt = obs.get('dt', 0.1)
    hold_s = obs.get('motion', {}).get('hold_s', 0.0)
    hitch_deg = obs.get('hitch_deg', 0.0)
    prog = obs.get('progress', {}).get('covered', 8.3)
    v_mps = obs.get('motion', {}).get('v_mps', 0.0)

    # Keep gaze steady at +64 deg so visual views are not interrupted by head movements
    look_deg = 64.0

    if hold_s > 0.0:
        return {'steer_deg': -20.0, 'speed_mps': 0.0, 'look_deg': look_deg}

    # Pull forward 1.5m to gain clearance from the right rail contact point
    if state == 'PULL_FWD':
        if v_mps > 0.05:
            unpin_fwd += v_mps * dt
        if unpin_fwd < 1.5:
            return {'steer_deg': -10.0, 'speed_mps': 0.7, 'look_deg': look_deg}
        else:
            state = 'JACK_LEFT'

    # Establish hitch angle > +12 deg before reversing through the curve
    if state == 'JACK_LEFT':
        if hitch_deg < 12.0:
            return {'steer_deg': -25.0, 'speed_mps': -0.4, 'look_deg': look_deg}
        else:
            state = 'FOLLOW_CURVE'

    # S-bend curve tracking
    if prog < 18.0:
        target_hitch = 14.0
    elif prog < 22.0:
        frac = (prog - 18.0) / 4.0
        target_hitch = 14.0 - frac * 28.0
    elif prog < 33.0:
        target_hitch = -14.0
    elif prog < 38.0:
        frac = (prog - 33.0) / 5.0
        target_hitch = -14.0 + frac * 14.0
    else:
        target_hitch = 0.0

    # Hitch angle controller
    dhitch = (hitch_deg - prev_hitch) / max(0.01, dt)
    prev_hitch = hitch_deg

    err = hitch_deg - target_hitch
    steer = 2.0 * err + 0.3 * dhitch
    steer = max(-35.0, min(35.0, steer))

    speed = -0.5
    return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': look_deg}

