import math

state = 'PULL_FWD'
fwd_d = 0.0

def control(obs):
    global state, fwd_d
    dt = obs.get('dt', 0.1)
    hold_s = obs.get('motion', {}).get('hold_s', 0.0)
    hitch_deg = obs.get('hitch_deg', 0.0)
    v_mps = obs.get('motion', {}).get('v_mps', 0.0)

    look_deg = -64.0

    if hold_s > 0.0:
        return {'steer_deg': 0.0, 'speed_mps': 0.0, 'look_deg': look_deg}

    # Pull forward 2.5m with straight steering to clear the contact point and straighten combination
    if state == 'PULL_FWD':
        if v_mps > 0.05:
            fwd_d += v_mps * dt
        if fwd_d < 2.5:
            return {'steer_deg': 0.0, 'speed_mps': 0.8, 'look_deg': look_deg}
        else:
            state = 'REVERSE_CORRIDOR'

    views = obs.get('views', {})
    left_rails = []
    right_rails = []

    for vname, vdata in views.items():
        orig = vdata.get('origin', [0, 0])
        for b_deg, d in vdata.get('walls', []):
            rad = math.radians(b_deg)
            px = orig[0] + d * math.cos(rad)
            py = orig[1] + d * math.sin(rad)
            if px < 0.0:
                if py > 0:
                    left_rails.append((px, py))
                else:
                    right_rails.append((px, py))

    min_l = min([p[1] for p in left_rails], default=999.0)
    max_r = max([p[1] for p in right_rails], default=-999.0)

    target_hitch = 0.0
    if min_l < 500.0 and max_r > -500.0:
        mid_y = (min_l + max_r) / 2.0
        target_hitch = max(-15.0, min(15.0, mid_y * 15.0))
    elif min_l < 1.8:
        target_hitch = -8.0
    elif max_r > -1.8:
        target_hitch = 8.0
    else:
        target_hitch = 0.0

    err = hitch_deg - target_hitch
    steer = 1.8 * err
    steer = max(-30.0, min(30.0, steer))

    t_sim = obs.get('t', 0.0)
    look = -64.0 if (int(t_sim / 3.0) % 2 == 0) else 64.0

    return {'steer_deg': steer, 'speed_mps': -0.45, 'look_deg': look}

