# Leg 4: Maneuver away from left rail and reverse along L-turn corridor
import math

state = {
    'phase': 'PULL_FWD',
    'fwd_dist': 0.0,
    'prev_prog': None
}

def control(obs):
    look_deg = -41.0  # Keep camera screen visible
    hitch = obs.get('hitch_deg', 0.0)
    prog = obs.get('progress', {}).get('covered', 0.0)

    if state['prev_prog'] is None:
        state['prev_prog'] = prog

    d_prog = prog - state['prev_prog']
    state['prev_prog'] = prog

    # Phase 1: Pull forward to clear contact and shift trailer body right
    if state['phase'] == 'PULL_FWD':
        if d_prog < 0:
            state['fwd_dist'] += abs(d_prog)

        # Pull forward ~4m steering left (+18 deg) so the rear swings right relative to rails
        if state['fwd_dist'] < 4.0:
            return {'steer_deg': 20.0, 'speed_mps': 1.2, 'look_deg': look_deg}
        else:
            state['phase'] = 'REVERSE'

    # Phase 2: Reverse following curve
    speed_mps = -0.75  # slow and steady to ensure steering authority

    views = obs.get('views', {})
    cam = views.get('camera')

    target_hitch = 0.0
    if cam and 'target_corners' in cam and cam['target_corners']:
        tc = cam['target_corners']
        cam_heading = (180.0 - hitch)
        t_lat = [d * math.sin(math.radians((b - cam_heading + 180.0) % 360.0 - 180.0)) for b, d in tc]
        avg_lat = sum(t_lat) / len(t_lat)
        target_hitch = max(-22.0, min(22.0, -avg_lat * 6.0))
    elif cam and 'walls' in cam:
        walls = cam['walls']
        cam_heading = (180.0 - hitch)

        left_dists = []
        right_dists = []
        for b_deg, d in walls:
            rel_angle = (b_deg - cam_heading + 180.0) % 360.0 - 180.0
            lat = d * math.sin(math.radians(rel_angle))
            long = d * math.cos(math.radians(rel_angle))
            if 0.5 < long < 12.0:
                if lat > 0:
                    left_dists.append(lat - 1.28)
                else:
                    right_dists.append(-lat - 1.28)

        min_l = min(left_dists) if left_dists else 5.0
        min_r = min(right_dists) if right_dists else 5.0

        # Emergency offset if dangerously close to left rail
        if min_l < 0.8:
            target_hitch = -10.0  # steer trailer right
        elif min_r < 0.8:
            target_hitch = 10.0
        else:
            err_corr = min_l - min_r
            target_hitch = max(-25.0, min(25.0, -err_corr * 7.0))

    err = hitch - target_hitch
    steer_deg = err * 2.2
    steer_deg = max(-38.0, min(38.0, steer_deg))

    return {'steer_deg': steer_deg, 'speed_mps': speed_mps, 'look_deg': look_deg}

